208	/**
209	 * How a claim's live figures (the rate step and the late charge) are rounded: by the sheet's rounding mode in force on the
210	 * claim's date when one is; else a claim dated before the sheet's policy date rounds half up, one dated on or after it half
211	 * to even. A correction rounds by the date of the claim it corrects, not its own.
212	 */
213	public final class Rounding {
214	
215	    /** The rounding mode setting's values, as typed. */
216	    public static final String HALF_UP = "half-up", HALF_EVEN = "half-even";
217	
218	    private Rounding() {
219	    }
220	
221	    /** A rounding mode as stored in a dated setting (1: half up, 2: half to even); null for none. */
222	    public static BigDecimal code(String mode) {
223	        return HALF_UP.equals(mode) ? BigDecimal.ONE : HALF_EVEN.equals(mode) ? BigDecimal.valueOf(2) : null;
224	    }
225	
226	    /** A stored rounding mode's name ("" for none). */
227	    public static String name(BigDecimal code) {
228	        return code == null ? "" : code.intValue() == 1 ? HALF_UP : HALF_EVEN;
229	    }
230	
231	    /** A stored rounding mode; null for none. */
232	    public static RoundingMode mode(BigDecimal code) {
233	        return code == null ? null : code.intValue() == 1 ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
234	    }
235	
236	    /** @param modeOn the sheet's rounding mode in force on a date; null for none. */
237	    public static RoundingMode of(Claim claim, LocalDate policyDate, Function<LocalDate, RoundingMode> modeOn) {
238	        RoundingMode set = modeOn.apply(claim.getRoundingDate());
239	        if (set != null) {
240	            return set;
241	        }
242	        return claim.getRoundingDate().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
243	    }
244	}
