254	/**
255	 * The late charge on a claim: an OPEN (or PENDING) claim whose due-by (fixed when it was created) is before
256	 * the sheet's today gains, for each full 30 days it is overdue, the sheet's late percent in force on that
257	 * boundary date (its due-by plus 30, 60, 90 ... days) of its figure plus the charges of the boundaries before it
258	 * (compounding), each rounded like due, the charges added up
259	 * (a boundary whose percent is 0.00 adds nothing); a deferred claim is not overdue. A correction, or a claim whose late
260	 * charge a steward waived, has no late charge (a waived claim may still be overdue). A statement binds the claim's due as shown, the charge (and floor)
261	 * included: while bound, the claim's due is that figure as it is. Settling freezes the charge in.
262	 * The floor is applied to the rate figure first; the charge is worked on that floored figure.
263	 * With grace days (those of its person's grade in force on its date) the claim is overdue only once its due-by plus them is
264	 * before today, and the 30-day boundaries are counted from its due-by plus them.
265	 */
266	public final class LateCharge {
267	
268	    public static final int PERIOD_DAYS = 30;
269	
270	    private LateCharge() {
271	    }
272	
273	    /** The charge on a claim's figure; zero when it is not overdue or has no figure. */
274	    public static BigDecimal of(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
275	            RoundingMode rounding) {
276	        return of(claim, figure, pct, today, rounding, 0);
277	    }
278	
279	    /** As {@link #of(Claim, BigDecimal, Function, LocalDate, RoundingMode)}, with the claim's grace days. */
280	    public static BigDecimal of(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
281	            RoundingMode rounding, int grace) {
282	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(today)) {
283	            return BigDecimal.ZERO.setScale(2);
284	        }
285	        return asOpen(claim, figure, pct, today, rounding, grace);
286	    }
287	
288	    /** The charge the claim's figure would carry were it open, whatever its status; re-settling uses it. */
289	    public static BigDecimal asOpen(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
290	            RoundingMode rounding) {
291	        return asOpen(claim, figure, pct, today, rounding, 0);
292	    }
293	
294	    /** As {@link #asOpen(Claim, BigDecimal, Function, LocalDate, RoundingMode)}, with the claim's grace days. */
295	    public static BigDecimal asOpen(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
296	            RoundingMode rounding, int grace) {
297	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
298	        if (figure == null || claim.isCorrection() || claim.isWaived()) {
299	            return charge;
300	        }
301	        LocalDate lateFrom = lateFrom(claim, grace);
302	        long overdue = ChronoUnit.DAYS.between(lateFrom, today);
303	        long periods = overdue > 0 ? overdue / PERIOD_DAYS : 0;
304	        for (long n = 1; n <= periods; n++) {
305	            BigDecimal rate = pct.apply(lateFrom.plusDays(n * PERIOD_DAYS));
306	            if (rate != null && rate.signum() != 0) {
307	                charge = charge.add(Rates.due(figure.add(charge), rate, rounding));
308	            }
309	        }
310	        return charge;
311	    }
312	
313	    /** A claim's due from its figure (the rate figure): the figure raised to the floor in force on its date, with the late
314	     *  charge worked on that floored figure on top. A settled due, and the due a statement bound (its figure), are kept as they are; a correction has
315	     *  no floor and no charge; null stays null. */
316	    public static BigDecimal due(Claim claim, BigDecimal figure, BigDecimal floor, Function<LocalDate, BigDecimal> pct,
317	            LocalDate today, RoundingMode rounding) {
318	        return due(claim, figure, floor, pct, today, rounding, 0);
319	    }
320	
321	    /** As {@link #due(Claim, BigDecimal, BigDecimal, Function, LocalDate, RoundingMode)}, with the claim's grace days. */
322	    public static BigDecimal due(Claim claim, BigDecimal figure, BigDecimal floor, Function<LocalDate, BigDecimal> pct,
323	            LocalDate today, RoundingMode rounding, int grace) {
324	        if (figure == null || claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) {
325	            return figure;
326	        }
327	        BigDecimal base = floored(claim, figure, floor);
328	        return base.add(of(claim, base, pct, today, rounding, grace));
329	    }
330	
331	    /** The date a claim's lateness counts from: its due-by plus its grace days. */
332	    public static LocalDate lateFrom(Claim claim, int grace) {
333	        return claim.getDueBy() == null ? null : claim.getDueBy().plusDays(grace);
334	    }
335	
336	    /** A due raised to the floor; a correction has no floor. */
337	    public static BigDecimal floored(Claim claim, BigDecimal due, BigDecimal floor) {
338	        return due == null || floor == null || claim.isCorrection() || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
339	    }
340	}
