343	/**
344	 * A claim's status. It starts DRAFT; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. A clerk
345	 * settling above the clerk limit sends an OPEN claim to PENDING instead: a steward approves it
346	 * (-> SETTLED) or rejects it (-> OPEN); a PENDING claim may also be voided, and a steward may void a SETTLED claim
347	 * within 7 days of its settlement. A DRAFT claim may be deleted (-> DELETED, counting nowhere) and, on the same
348	 * sheet-today, restored (-> DRAFT). A claim whose due is above the review threshold in force on its date goes to REVIEW
349	 * when opened instead of OPEN; a steward's review makes it OPEN, and a REVIEW claim may be voided.
350	 */
351	public enum ClaimStatus {
352	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
353	
354	    /** Whether a claim in this status may move to the target status. */
355	    public boolean canBecome(ClaimStatus target) {
356	        return switch (target) {
357	            case OPEN, REVIEW -> this == DRAFT;
358	            case SETTLED, PENDING -> this == OPEN;
359	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
360	            case DELETED -> this == DRAFT;
361	            case DRAFT -> this == DELETED;
362	        };
363	    }
364	
365	    /** Only OPEN, PENDING and SETTLED claims count toward claimed and every total. */
366	    public boolean counts() {
367	        return this == OPEN || this == PENDING || this == SETTLED;
368	    }
369	
370	    /** OPEN and PENDING claims are open: their due is live, they go overdue and a hold covering their date takes them out of the totals (unless bound). */
371	    public boolean isOpen() {
372	        return this == OPEN || this == PENDING;
373	    }
374	}
