422	                claim.isWaived(), String.valueOf(claim.proofsOf(ProofKind.RECEIPT)),
423	                String.valueOf(claim.proofsOf(ProofKind.PHOTO)), claim.isHeld());
424	    }
425	
426	    /** The due a claim keeps whatever the rates do: fixed when settled, else bound by a statement. */
427	    public static java.math.BigDecimal fixedDue(Claim claim) {
428	        if (claim.getSettledDue() != null) return claim.getSettledDue();
429	        return claim.isBound() ? claim.getStatedDue() : null;
430	    }
431	
432	    public static List<ClaimResponse> from(List<Claim> claims) {
433	        return claims.stream().map(ClaimResponse::from).toList();
434	    }
435	}
