package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim by a person on a sheet. Mutable so an Apply step can change it in place. */
public class Claim {

    private final long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate correctedDate;
    private LocalDate dueBy;
    private Integer terms;
    private LocalDate deferredUntil;
    private int proofs;
    private String splitFrom;
    private java.util.List<String> log = java.util.List.of();

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public LocalDate getDate() { return date; }
    public String getNote() { return note; }
    public ClaimStatus getStatus() { return status; }
    /** The number given when the claim was opened (sheet-wide, or <period>-<n> / X-<n> within its period); null for a draft (a voided claim keeps the number it had). */
    public String getNumber() { return number; }
    /** The due fixed when the claim was settled; null while its due is live. */
    public BigDecimal getSettledDue() { return settledDue; }
    /** The user who opened the claim; null if it was never opened. */
    public String getOpenedBy() { return openedBy; }
    public void setPersonId(long personId) { this.personId = personId; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public void setDate(LocalDate date) { this.date = date; }
    public void setNote(String note) { this.note = note; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    public void setNumber(String number) { this.number = number; }
    /** Whether the person's last statement bound this claim to a figure. */
    public boolean isStated() { return stated; }
    /** The figure the last statement bound this claim to; null when unbound or when it was n/a. */
    public BigDecimal getStatedDue() { return statedDue; }
    /** Whether the last statement binds this claim's figure now (a PENDING claim included). */
    public boolean isBound() { return stated; }
    public void setStated(boolean stated) { this.stated = stated; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** The user who last edited the claim; null if it was never edited. */
    private String editedBy;
    public String getEditedBy() { return editedBy; }
    public void setEditedBy(String editedBy) { this.editedBy = editedBy; }
    /** The number of the SETTLED claim this correction corrects; null for any claim that is not a correction. */
    public String getCorrects() { return corrects; }
    public void setCorrects(String corrects) { this.corrects = corrects; }
    /** The date of the claim this correction corrects; null when it is not a correction or that claim is not found. */
    public void setCorrectedDate(LocalDate correctedDate) { this.correctedDate = correctedDate; }
    public LocalDate getCorrectedDate() { return correctedDate; }
    /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects, any other claim's its own. */
    public LocalDate getRoundingDate() { return correctedDate != null ? correctedDate : date; }
    /** The claim's due-by, fixed when it was created: its date plus the first of its person's own terms, their grade's terms and the sheet's terms in force on that date. */
    public LocalDate getDueBy() { return dueBy; }
    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
    /** The terms in business days its due-by was fixed with; null when it has no due-by. */
    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    /** The date that places the claim in its period: its due-by as fixed at creation (its date when it has none). */
    public LocalDate getPeriodDate() { return dueBy != null ? dueBy : date; }
    /** The date the claim was last deferred until; null if it was never deferred. */
    public LocalDate getDeferredUntil() { return deferredUntil; }
    public void setDeferredUntil(LocalDate deferredUntil) { this.deferredUntil = deferredUntil; }
    /** Whether the claim is deferred on the date: OPEN and deferred until a later date. A deferred claim counts in no
     *  total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today.isBefore(deferredUntil);
    }
    /** The last day (the sheet's today then) a reminder was written for the claim; null if it was never reminded. */
    private LocalDate remindedOn;
    public LocalDate getRemindedOn() { return remindedOn; }
    public void setRemindedOn(LocalDate remindedOn) { this.remindedOn = remindedOn; }
    /** Whether a steward has waived the claim's late charge (once ever): it bears no late charge from then on. */
    private boolean waived;
    public boolean isWaived() { return waived; }
    public void setWaived(boolean waived) { this.waived = waived; }
    /** Whether the claim is held: it still counts in every total. */
    private boolean held;
    public boolean isHeld() { return held; }
    public void setHeld(boolean held) { this.held = held; }
    /** Whether the claim has been escalated (once ever); set on a reminder that escalates it. */
    private boolean escalated;
    public boolean isEscalated() { return escalated; }
    public void setEscalated(boolean escalated) { this.escalated = escalated; }
    /** Whether this reminder escalated the claim (not stored: the reminder's own outcome). */
    private boolean escalating;
    public boolean isEscalating() { return escalating; }
    public void setEscalating(boolean escalating) { this.escalating = escalating; }
    /** The claim's proofs count: raised by one at a time. */
    public int getProofs() { return proofs; }
    public void setProofs(int proofs) { this.proofs = proofs; }

    /** How many of the claim's proofs are photos; the rest are receipts. */
    private int proofPhotos;
    public int getProofPhotos() { return proofPhotos; }
    public void setProofPhotos(int proofPhotos) { this.proofPhotos = proofPhotos; }

    /** How many of the claim's proofs are of the kind (receipt or photo). */
    public int proofsOf(String kind) {
        return ProofKind.PHOTO.equals(kind) ? proofPhotos : ProofKind.RECEIPT.equals(kind) ? proofs - proofPhotos : 0;
    }
    /** The number of the claim this claim was split from; null for any claim a split did not make. */
    public String getSplitFrom() { return splitFrom; }
    public void setSplitFrom(String splitFrom) { this.splitFrom = splitFrom; }

    /** The number of the bulk settle batch that settled the claim; null when it was settled one at a time, or never. */
    private Integer settleBatch;
    public Integer getSettleBatch() { return settleBatch; }
    public void setSettleBatch(Integer settleBatch) { this.settleBatch = settleBatch; }

    /** Whether the claim was added while its period was soft-closed. */
    private boolean lateEntry;
    public boolean isLateEntry() { return lateEntry; }
    public void setLateEntry(boolean lateEntry) { this.lateEntry = lateEntry; }

    /** The claim's external reference; null when it has none. */
    private String ref;
    public String getRef() { return ref; }
    public void setRef(String ref) { this.ref = ref; }

    /** The claim's tags: lower-cased, sorted and comma separated; null when it has none. */
    private String tags;
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }

    /** The reason the claim was voided with, from the sheet's list; null when none. */
    private String voidReason;
    public String getVoidReason() { return voidReason; }
    public void setVoidReason(String voidReason) { this.voidReason = voidReason; }

    /** The mark drawn when the claim arrived on its sheet: a forward-only rate applies to it only when saved before
     *  (its mark lower; see Rates). 0 for a claim from before marks were kept. */
    private long rateMark;
    public long getRateMark() { return rateMark; }
    public void setRateMark(long rateMark) { this.rateMark = rateMark; }

    /** The user whose open editor locks the claim; null when unlocked. */
    private String lockedBy;
    public String getLockedBy() { return lockedBy; }
    public void setLockedBy(String lockedBy) { this.lockedBy = lockedBy; }
    /** A correction is a claim with a negative amount: its due has no floor and no late charge. */
    public boolean isCorrection() { return amount.signum() < 0; }
    /** The claim's status log, oldest first: one "<STATUS> by <user> on <date> due=<due>" line per status it has had. */
    public java.util.List<String> getLog() { return log; }
    public void setLog(java.util.List<String> log) { this.log = log; }
    private java.util.List<ClaimComment> comments = java.util.List.of();
    /** The claim's comments, oldest first (empty unless listed). */
    public java.util.List<ClaimComment> getComments() { return comments; }
    public void setComments(java.util.List<ClaimComment> comments) { this.comments = comments; }
    private java.util.List<ClaimLine> lines = java.util.List.of();
    /** The claim's lines, oldest first (empty unless listed). */
    public java.util.List<ClaimLine> getLines() { return lines; }
    public void setLines(java.util.List<ClaimLine> lines) { this.lines = lines; }
    /** The status the claim had at the end of the day, as its status log records it (each line dated the sheet's
     *  today when the change was made); null when it was added after that day. */
    public ClaimStatus statusAt(LocalDate end) {
        ClaimStatus at = null;
        for (String line : log) {
            int on = line.lastIndexOf(" on ");
            int due = line.indexOf(" due=", on);
            if (on < 0 || due < 0) continue;
            if (!LocalDate.parse(line.substring(on + 4, due)).isAfter(end)) {
                at = ClaimStatus.valueOf(line.substring(0, line.indexOf(' ')));
            }
        }
        return at;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.function.Function;

/**
 * How a claim's live figures (the rate step and the late charge) are rounded: by the sheet's rounding mode in force on the
 * claim's date when one is; else a claim dated before the sheet's policy date rounds half up, one dated on or after it half
 * to even. A correction rounds by the date of the claim it corrects, not its own.
 */
public final class Rounding {

    /** The rounding mode setting's values, as typed. */
    public static final String HALF_UP = "half-up", HALF_EVEN = "half-even";

    private Rounding() {
    }

    /** A rounding mode as stored in a dated setting (1: half up, 2: half to even); null for none. */
    public static BigDecimal code(String mode) {
        return HALF_UP.equals(mode) ? BigDecimal.ONE : HALF_EVEN.equals(mode) ? BigDecimal.valueOf(2) : null;
    }

    /** A stored rounding mode's name ("" for none). */
    public static String name(BigDecimal code) {
        return code == null ? "" : code.intValue() == 1 ? HALF_UP : HALF_EVEN;
    }

    /** A stored rounding mode; null for none. */
    public static RoundingMode mode(BigDecimal code) {
        return code == null ? null : code.intValue() == 1 ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** @param modeOn the sheet's rounding mode in force on a date; null for none. */
    public static RoundingMode of(Claim claim, LocalDate policyDate, Function<LocalDate, RoundingMode> modeOn) {
        RoundingMode set = modeOn.apply(claim.getRoundingDate());
        if (set != null) {
            return set;
        }
        return claim.getRoundingDate().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.function.Function;
import net.officefloor.hq.app.rate.Rates;

/**
 * The late charge on a claim: an OPEN (or PENDING) claim whose due-by (fixed when it was created) is before
 * the sheet's today gains, for each full 30 days it is overdue, the sheet's late percent in force on that
 * boundary date (its due-by plus 30, 60, 90 ... days) of its figure plus the charges of the boundaries before it
 * (compounding), each rounded like due, the charges added up
 * (a boundary whose percent is 0.00 adds nothing); a deferred claim is not overdue. A correction, or a claim whose late
 * charge a steward waived, has no late charge (a waived claim may still be overdue). A statement binds the claim's due as shown, the charge (and floor)
 * included: while bound, the claim's due is that figure as it is. Settling freezes the charge in.
 * The floor is applied to the rate figure first; the charge is worked on that floored figure.
 * With grace days (those of its person's grade in force on its date) the claim is overdue only once its due-by plus them is
 * before today, and the 30-day boundaries are counted from its due-by plus them.
 */
public final class LateCharge {

    public static final int PERIOD_DAYS = 30;

    private LateCharge() {
    }

    /** The charge on a claim's figure; zero when it is not overdue or has no figure. */
    public static BigDecimal of(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
            RoundingMode rounding) {
        return of(claim, figure, pct, today, rounding, 0);
    }

    /** As {@link #of(Claim, BigDecimal, Function, LocalDate, RoundingMode)}, with the claim's grace days. */
    public static BigDecimal of(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
            RoundingMode rounding, int grace) {
        if (!claim.getStatus().isOpen() || claim.isDeferredOn(today)) {
            return BigDecimal.ZERO.setScale(2);
        }
        return asOpen(claim, figure, pct, today, rounding, grace);
    }

    /** The charge the claim's figure would carry were it open, whatever its status; re-settling uses it. */
    public static BigDecimal asOpen(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
            RoundingMode rounding) {
        return asOpen(claim, figure, pct, today, rounding, 0);
    }

    /** As {@link #asOpen(Claim, BigDecimal, Function, LocalDate, RoundingMode)}, with the claim's grace days. */
    public static BigDecimal asOpen(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
            RoundingMode rounding, int grace) {
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.isCorrection() || claim.isWaived()) {
            return charge;
        }
        LocalDate lateFrom = lateFrom(claim, grace);
        long overdue = ChronoUnit.DAYS.between(lateFrom, today);
        long periods = overdue > 0 ? overdue / PERIOD_DAYS : 0;
        for (long n = 1; n <= periods; n++) {
            BigDecimal rate = pct.apply(lateFrom.plusDays(n * PERIOD_DAYS));
            if (rate != null && rate.signum() != 0) {
                charge = charge.add(Rates.due(figure.add(charge), rate, rounding));
            }
        }
        return charge;
    }

    /** A claim's due from its figure (the rate figure): the figure raised to the floor in force on its date, with the late
     *  charge worked on that floored figure on top. A settled due, and the due a statement bound (its figure), are kept as they are; a correction has
     *  no floor and no charge; null stays null. */
    public static BigDecimal due(Claim claim, BigDecimal figure, BigDecimal floor, Function<LocalDate, BigDecimal> pct,
            LocalDate today, RoundingMode rounding) {
        return due(claim, figure, floor, pct, today, rounding, 0);
    }

    /** As {@link #due(Claim, BigDecimal, BigDecimal, Function, LocalDate, RoundingMode)}, with the claim's grace days. */
    public static BigDecimal due(Claim claim, BigDecimal figure, BigDecimal floor, Function<LocalDate, BigDecimal> pct,
            LocalDate today, RoundingMode rounding, int grace) {
        if (figure == null || claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) {
            return figure;
        }
        BigDecimal base = floored(claim, figure, floor);
        return base.add(of(claim, base, pct, today, rounding, grace));
    }

    /** The date a claim's lateness counts from: its due-by plus its grace days. */
    public static LocalDate lateFrom(Claim claim, int grace) {
        return claim.getDueBy() == null ? null : claim.getDueBy().plusDays(grace);
    }

    /** A due raised to the floor; a correction has no floor. */
    public static BigDecimal floored(Claim claim, BigDecimal due, BigDecimal floor) {
        return due == null || floor == null || claim.isCorrection() || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts DRAFT; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. A clerk
 * settling above the clerk limit sends an OPEN claim to PENDING instead: a steward approves it
 * (-> SETTLED) or rejects it (-> OPEN); a PENDING claim may also be voided, and a steward may void a SETTLED claim
 * within 7 days of its settlement. A DRAFT claim may be deleted (-> DELETED, counting nowhere) and, on the same
 * sheet-today, restored (-> DRAFT). A claim whose due is above the review threshold in force on its date goes to REVIEW
 * when opened instead of OPEN; a steward's review makes it OPEN, and a REVIEW claim may be voided.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether a claim in this status may move to the target status. */
    public boolean canBecome(ClaimStatus target) {
        return switch (target) {
            case OPEN, REVIEW -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
        };
    }

    /** Only OPEN, PENDING and SETTLED claims count toward claimed and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** OPEN and PENDING claims are open: their due is live, they go overdue and a hold covering their date takes them out of the totals (unless bound). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/** amount is shown with two decimals; status is DRAFT, OPEN, PENDING, SETTLED, VOID or DELETED; number is "" when none;
 *  due is the due fixed when the claim was settled, else the figure its person's last statement bound
 *  it to, "" while it is live (or bound to n/a); openedBy is "" when never opened; stated is whether
 *  the last statement bound it; corrects is the number a correction corrects, "" for any other claim;
 *  roundingDate is the date its rounding goes by (a correction's: the date of the claim it corrects);
 *  dueBy is the due-by fixed when the claim was created; log is its status log, oldest first (empty unless listed);
 *  deferredUntil is the date the claim was last deferred until, "" if never; proofs is its proofs count,
 *  proofReceipts and proofPhotos how many of them are receipts and photos;
 *  splitFrom is the number of the claim a split made it from, "" for any other claim; lockedBy is the user whose
 *  open editor locks it, "" when unlocked; lateEntry is whether it was added while its period was soft-closed;
 *  remindedOn is the last day a reminder was written for it, "" if never; ref is its external reference, "" for none;
 *  tags are its tags, sorted and comma separated, "" for none; voidReason is the reason it was voided with, "" for none;
 *  comments are its comments, oldest first, each "<user> on <date>: <text>" (empty unless listed);
 *  lines are its lines, oldest first, each "<label> <qty> x <unit>" (empty unless listed);
 *  batch is the number of the bulk settle batch that settled it, "" when settled one at a time or never;
 *  rateMark is the mark drawn when it arrived on the sheet: a forward-only rate applies to it only when its mark is lower;
 *  waived is whether a steward has waived its late charge; held is whether the claim is held. */
public record ClaimResponse(String id, String personId, String amount, String date, String note, String status,
        String number, String due, String openedBy, boolean stated, String corrects,
        String roundingDate, String dueBy, List<String> log, String deferredUntil, String proofs,
        String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref, String tags,
        String voidReason, List<String> comments, String batch, List<String> lines, long rateMark, boolean waived,
        String proofReceipts, String proofPhotos, boolean held) {

    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
                claim.getAmount().setScale(2).toPlainString(), claim.getDate().toString(), claim.getNote(),
                claim.getStatus().name(), claim.getNumber() == null ? "" : claim.getNumber(),
                fixedDue(claim) == null ? "" : fixedDue(claim).setScale(2).toPlainString(),
                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(), claim.isStated(),
                claim.getCorrects() == null ? "" : claim.getCorrects(),
                claim.getRoundingDate().toString(), claim.getDueBy().toString(), claim.getLog(),
                claim.getDeferredUntil() == null ? "" : claim.getDeferredUntil().toString(),
                String.valueOf(claim.getProofs()),
                claim.getSplitFrom() == null ? "" : claim.getSplitFrom(),
                claim.getLockedBy() == null ? "" : claim.getLockedBy(), claim.isLateEntry(),
                claim.getRemindedOn() == null ? "" : claim.getRemindedOn().toString(),
                claim.getRef() == null ? "" : claim.getRef(),
                claim.getTags() == null ? "" : claim.getTags(),
                claim.getVoidReason() == null ? "" : claim.getVoidReason(),
                claim.getComments().stream().map(ClaimComment::line).toList(),
                claim.getSettleBatch() == null ? "" : String.valueOf(claim.getSettleBatch()),
                claim.getLines().stream().map(ClaimLine::line).toList(), claim.getRateMark(),
                claim.isWaived(), String.valueOf(claim.proofsOf(ProofKind.RECEIPT)),
                String.valueOf(claim.proofsOf(ProofKind.PHOTO)), claim.isHeld());
    }

    /** The due a claim keeps whatever the rates do: fixed when settled, else bound by a statement. */
    public static java.math.BigDecimal fixedDue(Claim claim) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        return claim.isBound() ? claim.getStatedDue() : null;
    }

    public static List<ClaimResponse> from(List<Claim> claims) {
        return claims.stream().map(ClaimResponse::from).toList();
    }
}
package net.officefloor.hq.app.person;

import java.util.Set;

/** The person form's rules, shared by the form and the import box. */
public final class PersonRules {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private PersonRules() {
    }

    /** The person form's rules: the request trimmed and normalised, or refused. */
    public static PersonRequest check(PersonRequest request) throws InvalidPersonException {
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                java.time.LocalDate.parse(gradeFrom);
            } catch (java.time.format.DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more");
        }
        if (!terms.isEmpty()) {
            terms = String.valueOf(Integer.parseInt(terms));
        }
        String termsFrom = request.termsFrom() == null ? "" : request.termsFrom().trim();
        if (!termsFrom.isEmpty()) {
            try {
                java.time.LocalDate.parse(termsFrom);
            } catch (java.time.format.DateTimeParseException e) {
                throw new InvalidPersonException("The terms' from-date must be a date");
            }
        }
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        String tags = net.officefloor.hq.app.claim.Tags.normalise(request.tags());
        return new PersonRequest(name, grade, request.user(), request.version(), gradeFrom, terms, contact, tags == null ? "" : tags, termsFrom);
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** statementCount is how many statements were taken; statedTotal is the last one's due-total ("n/a" when it
 *  was n/a, "" when none was taken); statementDate is the sheet's today when it was taken ("" when none); retired says whether a retirement date is set and retiredFrom is it ("" when none); held says whether they have any hold and holds lists each (from, to; to "" when open-ended), in the order added; patrons are the names of the people they named as patrons, sorted, and patronIds their ids; grade is the grade in force on the sheet's today and grades every grade recorded, by from-date; terms is the person's own terms in days in force on the sheet's today ("" for none) and baseTerms those from the beginning of time; contact is the person's contact ("" for none); tags are the person's tags, sorted and comma separated ("" for none); aliases are the person's aliases, sorted as names are compared; clashing says whether their name or an alias is used by someone else on a sheet of the sheet's tree; origin is the sheet they were transferred from ("" for none); retirements are their past retirements, each "<from> to <to>", in the order they ended; snapshots are their SNAPSHOT lines, each "<the day being left> <due-total>", oldest first; statements are their statements still standing, each "<statement date> <due-total>", in the order taken; flag is the reason of a steward's flag while the sheet's today is on or before its until date ("" otherwise); approver is the user who may approve or reject their PENDING claims ("" for none). */
public record PersonResponse(String id, String name, String grade, int version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom, boolean held,
        List<HoldFrom> holds,
        List<String> patrons, List<String> patronIds, List<GradeFrom> grades, String terms, String contact, String tags,
        List<String> aliases, boolean clashing, String origin, List<String> retirements, List<String> snapshots,
        List<String> statements, String baseTerms, String flag, String approver) {

    /** A grade in force from a date (YYYY-MM-DD; "" for the beginning of time). */
    public record GradeFrom(String from, String grade) {
    }

    /** A hold from a date to a date (YYYY-MM-DD; to "" when open-ended). */
    public record HoldFrom(String from, String to) {
    }

    public static PersonResponse from(Person person) {
        boolean stated = person.getStatementCount() > 0;
        return new PersonResponse(String.valueOf(person.getId()), person.getName(), person.getGrade(), person.getVersion(),
                person.getStatementCount(),
                !stated ? "" : person.getStatedTotal() == null ? "n/a" : person.getStatedTotal().setScale(2).toPlainString(),
                person.getStatementDate() == null ? "" : person.getStatementDate().toString(),
                person.isRetired(), person.getRetiredFrom() == null ? "" : person.getRetiredFrom().toString(),
                person.isHeld(),
                person.getHolds().stream().map(h -> new HoldFrom(h.from().toString(), h.to() == null ? "" : h.to().toString())).toList(),
                List.copyOf(person.getPatronNames()),
                person.getPatronIds().stream().map(String::valueOf).toList(),
                person.getGrades().entrySet().stream().map(e -> new GradeFrom(
                        e.getKey().equals(Person.BEGINNING) ? "" : e.getKey().toString(), e.getValue())).toList(),
                person.getTermsShown() == null ? "" : String.valueOf(person.getTermsShown()),
                person.getContact() == null ? "" : person.getContact(),
                person.getTags() == null ? "" : person.getTags(),
                List.copyOf(person.getAliases()), person.isClashing(),
                person.getOrigin() == null ? "" : person.getOrigin(),
                person.getRetirements().stream().map(r -> r.from() + " to " + r.to()).toList(),
                List.copyOf(person.getSnapshots()),
                List.copyOf(person.getStatements()),
                person.getTerms() == null ? "" : String.valueOf(person.getTerms()),
                person.getFlagShown(),
                person.getApprover() == null ? "" : person.getApprover());
    }

    public static List<PersonResponse> from(List<Person> people) {
        return people.stream().map(PersonResponse::from).toList();
    }
}

