import { isDeferred, isOpen } from '../claims/useClaims';
import { lateFrom } from '../claims/overdue';
import type { Grace } from '../claims/useGrace';

// Due is worked in exact integers: an amount in cents times a rate in hundredths of a percent is
// due in millionths, then rounded to cents — by the sheet's rounding mode in force on the claim's date, else half up
// for a claim dated before the sheet's policy date, half to even for one dated on or after it. No float ever touches it.

export const NA = 'n/a';

/** "10.25" -> 1025n. */
export function toCents(amount: string): bigint {
  const negative = amount.trim().startsWith('-');
  const [whole, frac = ''] = amount.trim().replace(/^[-+]/, '').split('.');
  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

/** 1025n -> "10.25". */
export function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const frac = (abs % 100n).toString().padStart(2, '0');
  return `${negative ? '-' : ''}${abs / 100n}.${frac}`;
}

/** The due on an amount of cents at a rate ("12.50"), in cents, rounded half up or else half to
 *  even; null when there is no rate. */
export function dueCents(cents: bigint, rate: string | undefined, halfUp = false): bigint | null {
  if (rate === undefined) return null;
  const millionths = cents * toCents(rate);
  const negative = millionths < 0n;
  const abs = negative ? -millionths : millionths;
  const whole = abs / 10000n;
  const rest = abs % 10000n;
  const rounded = rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
  return negative ? -rounded : rounded;
}

/** A due for display: two decimals, or n/a. */
export function showDue(due: bigint | null): string {
  return due === null ? NA : formatCents(due);
}

/** A live due raised to a floor ("1.00"); n/a stays n/a. */
export function floored(due: bigint | null, floor: string): bigint | null {
  if (due === null) return null;
  const min = toCents(floor);
  return due < min ? min : due;
}

/** The value of a dated setting in force on a date (a claim's: its date), e.g. "1.00". */
export type On = (date: string) => string;

/** What a late charge needs: the sheet's late percent in force on a date (a boundary's, "10.00"), its today and each
 *  claim's grace days (none when left out). */
export type Late = { pct: On; today: string | undefined; grace?: Grace };

const DAY_MS = 86_400_000;

/** How the sheet's claims round: its policy date (blank: the sheet's today; undefined while loading) and every
 *  rounding mode recorded (half-up, half-even; "" for none), oldest from-date first. */
export type Policy = { date: string | undefined; rounding: { from: string; value: string }[] };

/** Whether a claim's live figures round half up: by the rounding mode in force on its rounding date (a correction's is
 *  the date of the claim it corrects) when one is, else when that date is before the sheet's policy date. */
export function roundsHalfUp(claim: { roundingDate?: string; date: string }, policy: Policy | undefined): boolean {
  const on = claim.roundingDate || claim.date;
  const mode = (policy?.rounding ?? []).filter((d) => d.from <= on).pop()?.value ?? '';
  if (mode !== '') return mode === 'half-up';
  return policy?.date !== undefined && policy.date !== '' && on < policy.date;
}

/** A claim with a negative amount is a correction: its due has no floor and no late charge. */
export const isCorrection = (claim: { amount?: string }) => claim.amount !== undefined && toCents(claim.amount) < 0n;

/** The late charge on a figure in cents: an OPEN (or PENDING) claim whose due-by (fixed when it was created) is
 *  before today (and that is not deferred) gains, for each full 30 days it is overdue, the late percent in force on that
 *  boundary date (its due-by plus its grace days plus 30, 60, 90 ... days) of its figure plus the charges of the boundaries
 *  before it (compounding), each rounded like due, the charges added up. A statement binds it into the due it binds; settling freezes it into the settled due.
 *  A claim whose late charge a steward waived gains none, whatever its overdue state. */
export function lateCents(claim: { amount?: string; date: string; status?: string; roundingDate?: string; dueBy?: string; deferredUntil?: string; personId?: string; waived?: boolean }, figure: bigint, late: Late | undefined, policy?: Policy): bigint {
  if (late === undefined || late.today === undefined || !claim.dueBy || claim.waived || !isOpen(claim) || isDeferred(claim, late.today) || isCorrection(claim)) return 0n;
  const from = lateFrom(claim, late.grace);
  const days = Math.round((Date.parse(late.today) - Date.parse(from)) / DAY_MS);
  const periods = days > 0 ? Math.floor(days / 30) : 0;
  const halfUp = roundsHalfUp(claim, policy);
  let charge = 0n;
  for (let n = 1; n <= periods; n++) {
    const boundary = new Date(Date.parse(from) + n * 30 * DAY_MS).toISOString().slice(0, 10);
    charge += dueCents(figure + charge, late.pct(boundary), halfUp) ?? 0n;
  }
  return charge;
}

/** A claim's due: the one fixed when it was settled, frozen as it is; else the due a statement bound it to, as it was shown
 *  then (late charge and floor included; a claim bound to n/a stays n/a); else its amount at the current rate, raised first to the floor in force on its
 *  date, with an overdue claim's late charge (each 30-day boundary at the late percent in force on it) worked on that
 *  floored figure and added on top. A correction is never floored and gains no late charge. Live
 *  figures round by the sheet's rounding mode or policy date (see roundsHalfUp). */
export function claimDue(
  claim: { amount: string; due: string; date: string; status?: string; stated?: boolean; roundingDate?: string; dueBy?: string; deferredUntil?: string; personId?: string; waived?: boolean },
  rate: string | undefined,
  floor: On,
  late?: Late,
  policy?: Policy,
): bigint | null {
  if (claim.due !== '' && (claim.status === 'SETTLED' || claim.stated)) return toCents(claim.due);
  const figure = claim.due !== '' ? toCents(claim.due) : claim.stated ? null : dueCents(toCents(claim.amount), rate, roundsHalfUp(claim, policy));
  if (figure === null) return null;
  const base = isCorrection(claim) ? figure : floored(figure, floor(claim.date))!;
  return base + lateCents(claim, base, late, policy);
}

/** A person's due-total: the sum of the figures of their claims that count. With no rate for their
 *  grade today it is n/a, unless a claim keeps a figure (a settled one, or one worked at the grade
 *  in force on its date); then it is the sum of the figures there are. A claim whose figure is n/a
 *  adds nothing. */
export function dueTotal(
  claims: { amount: string; due: string; date: string; status?: string; stated?: boolean; roundingDate?: string; dueBy?: string; personId?: string; rateMark?: number }[],
  rateOf: (claim: { date: string; rateMark?: number }) => string | undefined,
  rateToday: string | undefined,
  floor: On,
  late?: Late,
  policy?: Policy,
): bigint | null {
  const figures = claims.map((c) => claimDue(c, rateOf(c), floor, late, policy));
  if (rateToday === undefined && figures.every((f) => f === null)) return null;
  return figures.reduce<bigint>((sum, f) => sum + (f ?? 0n), 0n);
}

/** A due-total held to the sheet's cap ("" for none): the cap when it is above it. n/a is not capped. */
export function capped(total: bigint | null, cap: string): bigint | null {
  if (total === null || cap === '') return total;
  const max = toCents(cap);
  return total > max ? max : total;
}

/** How far a due-total is above the sheet's cap; 0 when it is not, or is n/a. */
export function excess(total: bigint | null, cap: string): bigint {
  const held = capped(total, cap);
  return total === null || held === null ? 0n : total - held;
}
import { isDeferred, isOpen, type Claim } from './useClaims';
import type { Grace } from './useGrace';

/** A claim's due-by: fixed when it was created, from the terms of its person's grade in force on its date. */
export const dueBy = (c: Claim) => c.dueBy;

/** The date a claim's lateness counts from: its due-by plus its grace days (see useGrace). */
export function lateFrom(c: { dueBy?: string; personId?: string; date: string }, grace?: Grace): string {
  const days = grace === undefined ? 0 : grace(c);
  if (!c.dueBy || days === 0) return c.dueBy ?? '';
  const d = new Date(`${c.dueBy}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** A claim is overdue when it is OPEN (or PENDING), not deferred, and its due-by plus its grace days is before the sheet's today. */
export const isOverdue = (c: Claim, today: string | undefined, grace?: Grace) =>
  isOpen(c) && !isDeferred(c, today) && today !== undefined && lateFrom(c, grace) < today;
import type { Claim } from './useClaims';

/** A claim's review day: the sheet's today when it last went to REVIEW (its latest REVIEW log line), "" if never. */
export function reviewDay(c: Claim): string {
  const line = [...(c.log ?? [])].reverse().find((l) => l.startsWith('REVIEW by '));
  return line?.match(/ on (\d{4}-\d{2}-\d{2}) /)?.[1] ?? '';
}

/** A claim is review-late when it is REVIEW, the sheet has a review SLA ("" for none) and its review day plus the
 *  SLA days is before the sheet's today. */
export function isReviewLate(c: Claim, today: string | undefined, sla: string | undefined): boolean {
  const day = reviewDay(c);
  if (c.status !== 'REVIEW' || today === undefined || !sla || day === '') return false;
  const d = new Date(`${day}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + Number(sla));
  return d.toISOString().slice(0, 10) < today;
}
import { gradeOn, usePeople } from '../people/usePeople';
import { inForce, useSettings } from '../settings/useSettings';

/** A claim's grace days: those of its person's grade in force on its date, as in force on that date (0 for none). */
export type Grace = (claim: { personId?: string; date: string }) => number;

export function useGrace(sheet: string): Grace {
  const settings = useSettings(sheet);
  const people = usePeople(sheet);
  const byId = new Map(people.map((p) => [p.id, p]));
  return (claim) => {
    const person = claim.personId === undefined ? undefined : byId.get(claim.personId);
    if (person === undefined) return 0;
    const days = inForce(settings, `grace-${gradeOn(person, claim.date)}`, claim.date, '');
    return days === '' ? 0 : Number.parseInt(days, 10);
  };
}
import { countsClaimed, countsLive, hasTag, isOpen, useClaims, useTags } from '../claims/useClaims';
import { isOverdue } from '../claims/overdue';
import { useGrace } from '../claims/useGrace';
import { isReviewLate } from '../claims/reviewLate';
import { capped, claimDue, dueTotal, excess, formatCents, toCents } from '../rates/due';
import { claimRate, rateOn, useRates } from '../rates/useRates';
import { useCap, useFloor, useLatePct, usePolicy, useSettings } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { gradeOn, retiredOn, usePeople, type Person } from './usePeople';

export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

// The figures the people list, its totals, the summary and the header are all worked from, so
// every place that repeats a figure shows the same one.
export function useSheetFigures(sheet: string) {
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const tags = useTags(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const grace = useGrace(sheet);
  const late = { pct: useLatePct(sheet), today, grace };
  const policy = usePolicy(sheet);
  const cap = useCap(sheet);
  const reviewSla = useSettings(sheet)?.reviewSla;
  const byId = new Map(people.map((p) => [p.id, p]));
  const live = claims.filter((c) => {
    const person = byId.get(c.personId);
    return person !== undefined && countsLive(c, retiredOn(person, today), today);
  });
  // The claims that count toward claimed: a held claim does, as it does in every total.
  const claimedLive = claims.filter((c) => {
    const person = byId.get(c.personId);
    return person !== undefined && countsClaimed(c, retiredOn(person, today), today);
  });
  // A claim is worked at the grade in force on its date; the row shows the one in force today.
  // The sum of a person's figures, before the cap.
  const uncappedOf = (person: Person) =>
    dueTotal(
      live.filter((c) => c.personId === person.id),
      (c) => claimRate(rates, gradeOn(person, c.date), c),
      rateOn(rates, gradeOn(person, today), today),
      floor,
      late,
      policy,
    );
  // A person's due-total: at most the sheet's cap (n/a is not capped); everything that adds up
  // due-totals uses it. Their excess is how far the sum of their figures is above the cap.
  const totalOf = (person: Person) => capped(uncappedOf(person), cap);
  const excessOf = (person: Person) => excess(uncappedOf(person), cap);
  // A person's settled-total and open-total: the dues of their counting SETTLED claims (frozen
  // figures, corrections included), and of their counting OPEN and PENDING claims; n/a adds nothing.
  // Together they make the sum of their figures before the cap.
  const dueSumOf = (person: Person, which: (c: (typeof live)[number]) => boolean) =>
    live
      .filter((c) => c.personId === person.id && which(c))
      .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n), 0n);
  const settledTotalOf = (person: Person) => dueSumOf(person, (c) => c.status === 'SETTLED');
  const openTotalOf = (person: Person) => dueSumOf(person, isOpen);
  // The sheet's settled-total and open-total: everyone's figure added up, not trimmed.
  const sheetSettledTotal = formatCents(people.reduce((sum, p) => sum + settledTotalOf(p), 0n));
  const sheetOpenTotal = formatCents(people.reduce((sum, p) => sum + openTotalOf(p), 0n));
  const overdue = live.filter((c) => isOverdue(c, today, grace));
  const overdueSum = (cs: typeof overdue) =>
    cs.reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n);
  const overdueTotal = (cs: typeof overdue) => formatCents(overdueSum(cs));
  // The sheet's due-total: the people's due-totals added up, skipping n/a, trimmed.
  const sheetDueTotal = formatCents(trimmedSum(people.map(totalOf).filter((due): due is bigint => due !== null)));
  // The sheet's overdue-total: each person's overdue-total (always a figure) added up, trimmed.
  const sheetOverdueTotal = formatCents(trimmedSum(people.map((p) => overdueSum(overdue.filter((c) => c.personId === p.id)))));
  // Active: an OPEN or PENDING claim that counts, dated within the 30 days up to and including today.
  const activeFrom = today === undefined ? undefined : daysBefore(today, 29);
  const isActive = (person: Person) =>
    activeFrom !== undefined &&
    live.some((c) => c.personId === person.id && isOpen(c) && c.date >= activeFrom && c.date <= today!);
  // Settled: the sum of a person's SETTLED claims' frozen figures, dated within the 90 days up to and including today.
  const settledFrom = today === undefined ? undefined : daysBefore(today, 89);
  const recentSettledOf = (person: Person) =>
    settledFrom === undefined
      ? 0n
      : claims
          .filter((c) => c.personId === person.id && c.status === 'SETTLED' && c.date >= settledFrom && c.date <= today! && /^-?\d+\.\d{2}$/.test(c.due))
          .reduce((sum, c) => sum + toCents(c.due), 0n);
  // Aged: the dues of a person's OPEN and PENDING claims that count, split by the claim's age on
  // today (days from its date): 0 to 30, 31 to 60, 61 or more; a claim dated after today is 0 to 30.
  const agedOf = (person: Person) => {
    const buckets = [0n, 0n, 0n];
    if (today === undefined) return buckets;
    for (const c of live) {
      if (c.personId !== person.id || !isOpen(c)) continue;
      const age = daysBetween(c.date, today);
      const due = claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n;
      buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2] += due;
    }
    return buckets;
  };
  // The sheet's aged buckets: the people's buckets added up, not trimmed.
  const sheetAged = people
    .map(agedOf)
    .reduce((sum, b) => sum.map((v, i) => v + b[i]), [0n, 0n, 0n])
    .map(formatCents);
  // Each tag ever used on the sheet with its due-total: the dues of the counting claims that carry it,
  // or whose person carries it, each claim once (a claim with two tags counts in both); n/a adds nothing.
  const tagTotals = tags.map((tag) => ({
    tag,
    total: formatCents(
      live
        .filter((c) => hasTag(c, tag) || hasTag(byId.get(c.personId)!, tag))
        .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n),
    ),
  }));
  const onSheet = new Set(people.map((p) => p.id));
  const sheetClaims = claims.filter((c) => onSheet.has(c.personId));
  // Each calendar month (yyyy-mm) any claim on the sheet is dated in, earliest first, with its
  // due-total: the dues of the counting claims dated in it; n/a adds nothing.
  const monthTotals = [...new Set(sheetClaims.map((c) => c.date.slice(0, 7)))].sort().map((month) => ({
    month,
    total: formatCents(
      live
        .filter((c) => c.date.slice(0, 7) === month)
        .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n),
    ),
  }));
  const statusCount = (s: (typeof STATUSES)[number]) => sheetClaims.filter((c) => c.status === s).length;
  // Review-late: REVIEW claims whose review day plus the sheet's review SLA is before the sheet's today.
  const reviewLateCount = sheetClaims.filter((c) => isReviewLate(c, today, reviewSla)).length;
  const voidReasonCount = (reason: string) => sheetClaims.filter((c) => c.status === 'VOID' && c.voidReason === reason).length;
  return { people, claims, rates, today, byId, live, claimedLive, totalOf, excessOf, overdue, overdueTotal, sheetDueTotal, sheetOverdueTotal, statusCount, reviewLateCount, voidReasonCount, isActive, recentSettledOf, agedOf, sheetAged, settledTotalOf, openTotalOf, sheetSettledTotal, sheetOpenTotal, tagTotals, monthTotals };
}

// People's figures added up, leaving out the single highest and the single lowest when there are
// three or more.
function trimmedSum(figures: bigint[]): bigint {
  const sum = figures.reduce((a, b) => a + b, 0n);
  if (figures.length < 3) return sum;
  const max = figures.reduce((a, b) => (b > a ? b : a));
  const min = figures.reduce((a, b) => (b < a ? b : a));
  return sum - max - min;
}

// The ISO date `days` days before `date`.
function daysBefore(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - days);
  return d.toISOString().slice(0, 10);
}

// The whole days from one ISO date to a later one (negative when it is earlier).
function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
}

