  log: string[];
  /** Whether a steward has waived the claim's late charge: it bears none from then on, whatever its overdue state. */
  waived?: boolean;
  /** Whether the claim is held: it still counts in every total. */
  held?: boolean;
  /** The date the claim was last deferred until, "" if it was never deferred. */
  deferredUntil: string;
  /** The claim's proofs count. */
  proofs: string;
  /** How many of the claim's proofs are receipts. */
  proofReceipts?: string;
  /** How many of the claim's proofs are photos. */
  proofPhotos?: string;
  /** The number of the claim a split made this claim from, "" for any other claim. */
  splitFrom: string;
  /** The user whose open editor locks the claim for everyone else, "" when unlocked. */
  lockedBy?: string;
  /** Whether the claim was added while its period was soft-closed. */
  lateEntry?: boolean;
  /** The last day (the sheet's today then) a reminder was written for the claim, "" if never. */
  remindedOn?: string;
  /** The reason the claim was voided with, from the sheet's list; "" for none. */
  voidReason?: string;
  /** The claim's comments, oldest first: "<user> on <date>: <text>" each, the date the sheet's today when it was written. */
  comments?: string[];
  /** The claim's lines, oldest first: "<label> <qty> x <unit>" each; with lines, its amount is their amounts added up. */
  lines?: string[];
  /** The number of the bulk settle batch that settled the claim, "" when it was settled one at a time or never. */
  batch?: string;
