package net.officefloor.hq.app.person;

/** A person on a sheet. Mutable so an Apply step can change it in place. */
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

public class Person {

    /** The from-date standing for the beginning of time (stored as a null from-date). */
    public static final LocalDate BEGINNING = LocalDate.MIN;

    private final long id;
    private final String sheetId;
    private String name;
    /** The person's grades by the date each is in force from; {@link #BEGINNING} is the beginning of time. */
    private final java.util.TreeMap<LocalDate, String> grades = new java.util.TreeMap<>();
    /** The sheet's today when the person was loaded: the grade in force on it is the one shown. */
    private LocalDate today;
    /** A grade recorded by this edit and not yet written: its from-date and grade. */
    private java.util.Map.Entry<LocalDate, String> recorded;
    private int version;
    /** The person's own terms in days; null when they have none (their grade's or the sheet's apply). */
    private Integer terms;
    /** Whether this edit changed the person's terms from those loaded. */
    private boolean termsChanged;
    private int statementCount;
    private BigDecimal statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    /** The person's holds, in the order they were added. */
    private java.util.List<Hold> holds = new java.util.ArrayList<>();
    private java.util.List<Long> patronIds = new java.util.ArrayList<>();
    private java.util.List<String> patronNames = new java.util.ArrayList<>();
    /** The person's aliases, sorted as names are compared. */
    private java.util.List<String> aliases = new java.util.ArrayList<>();
    /** Whether the person's name or an alias is used by someone else on a sheet of the sheet's tree. */
    private boolean clashing;

    public Person(long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(long id, String sheetId, String name, String grade, int version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grades.put(BEGINNING, grade);
        this.version = version;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    /** The grade in force on the sheet's today. */
    public String getGrade() { return gradeOn(today); }
    /** The grade in force on a date: the one with the latest from-date on or before it; with no date, the first. */
    public String gradeOn(LocalDate date) {
        java.util.Map.Entry<LocalDate, String> found = date == null ? null : grades.floorEntry(date);
        return found == null ? grades.firstEntry().getValue() : found.getValue();
    }
    /** The person's grades by from-date ({@link #BEGINNING} for the first), earliest first. */
    public java.util.SortedMap<LocalDate, String> getGrades() { return java.util.Collections.unmodifiableSortedMap(grades); }
    public void setGrades(java.util.Map<LocalDate, String> loaded) {
        if (!loaded.isEmpty()) {
            grades.clear();
            grades.putAll(loaded);
        }
    }
    /** Records the grade from the date (replacing one recorded from that same date), to be written on save. */
    public void recordGrade(LocalDate from, String grade) {
        grades.put(from, grade);
        recorded = java.util.Map.entry(from, grade);
    }
    /** The grade this edit recorded and has not written yet; null when none. */
    public java.util.Map.Entry<LocalDate, String> getRecordedGrade() { return recorded; }
    public void clearRecordedGrade() { recorded = null; }
    public LocalDate getToday() { return today; }
    public void setToday(LocalDate today) { this.today = today; }
    public int getVersion() { return version; }
    /** The person's own terms in days; null when none. */
    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    /** Sets the terms the form gave, noting whether they differ from those the person had or from those in force
     *  on the sheet's today. */
    public void editTerms(Integer terms) {
        termsChanged = !java.util.Objects.equals(this.terms, terms) || !java.util.Objects.equals(getTermsShown(), terms);
        this.terms = terms;
    }
    public boolean isTermsChanged() { return termsChanged; }
    /** The person's terms dated from a from-date on (null terms: none from then), each until the next; before the
     *  first, {@link #getTerms()} are in force. */
    private final java.util.TreeMap<LocalDate, Integer> datedTerms = new java.util.TreeMap<>();
    /** Terms recorded by this edit and not yet written: their from-date. */
    private LocalDate recordedTermsFrom;
    public java.util.SortedMap<LocalDate, Integer> getDatedTerms() { return java.util.Collections.unmodifiableSortedMap(datedTerms); }
    public void setDatedTerms(java.util.Map<LocalDate, Integer> loaded) {
        datedTerms.clear();
        datedTerms.putAll(loaded);
    }
    /** Records the terms from the date (replacing those recorded from that same date), to be written on save. */
    public void recordTerms(LocalDate from, Integer terms) {
        termsChanged = !datedTerms.containsKey(from) || !java.util.Objects.equals(datedTerms.get(from), terms);
        datedTerms.put(from, terms);
        recordedTermsFrom = from;
    }
    /** The from-date of the terms this edit recorded and has not written yet; null when none. */
    public LocalDate getRecordedTermsFrom() { return recordedTermsFrom; }
    public void clearRecordedTerms() { recordedTermsFrom = null; }
    /** The person's own terms in force on a date: those with the latest from-date on or before it, else those from
     *  the beginning of time; null when none. */
    public Integer termsOn(LocalDate date) {
        java.util.Map.Entry<LocalDate, Integer> found = date == null ? null : datedTerms.floorEntry(date);
        return found == null ? terms : found.getValue();
    }
    /** The person's own terms in force on the sheet's today; null when none. */
    public Integer getTermsShown() { return termsOn(today); }
    /** The person's contact, trimmed and lower-cased; null when none. */
    private String contact;
    /** Whether this edit changed the person's contact from the one loaded. */
    private boolean contactChanged;
    public String getContact() { return contact; }
    public void setContact(String contact) { this.contact = contact; }
    /** Sets the contact the form gave, noting whether it differs from the one the person had. */
    public void editContact(String contact) {
        contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }
    public boolean isContactChanged() { return contactChanged; }
    /** The person's tags: lower-cased, sorted and comma separated; null when they have none. */
    private String tags;
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }
    /** How many statements have been taken for the person. */
    public int getStatementCount() { return statementCount; }
    /** The last statement's due-total; null when none was taken or it was n/a. */
    public BigDecimal getStatedTotal() { return statedTotal; }
    /** The sheet's today when the last statement was taken; null when none was. */
    public LocalDate getStatementDate() { return statementDate; }
    /** The date the person is retired from; null when not retired. Set means retired, whatever the date. */
    public LocalDate getRetiredFrom() { return retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    /** Whether a claim may be dated on this date: never after the person's retirement date, nor after the from-date
     *  and before the to-date of a past retirement. */
    public boolean allowsClaimOn(LocalDate date) {
        return (retiredFrom == null || !date.isAfter(retiredFrom))
                && retirements.stream().noneMatch(r -> r.excludes(date));
    }
    /** A past retirement: from its from-date to the day the person was unretired. */
    public record Retirement(LocalDate from, LocalDate to) {
        /** Whether a claim dated on the date falls within it: after the from-date and before the to-date. */
        public boolean excludes(LocalDate date) {
            return date != null && date.isAfter(from) && date.isBefore(to);
        }
    }
    /** The person's past retirements, in the order they ended. */
    private java.util.List<Retirement> retirements = new java.util.ArrayList<>();
    public java.util.List<Retirement> getRetirements() { return retirements; }
    public void setRetirements(java.util.List<Retirement> retirements) { this.retirements = retirements; }
    /** The person's SNAPSHOT lines, each "<the day being left> <due-total>", oldest first. */
    private java.util.List<String> snapshots = new java.util.ArrayList<>();
    public java.util.List<String> getSnapshots() { return snapshots; }
    public void setSnapshots(java.util.List<String> snapshots) { this.snapshots = snapshots; }

    /** The person's statements still standing, each "<statement date> <due-total>" (due-total "n/a" when it was n/a),
     *  oldest first — those a merge or a transfer brought over among them, by date. */
    private java.util.List<String> statements = new java.util.ArrayList<>();
    public java.util.List<String> getStatements() { return statements; }
    public void setStatements(java.util.List<String> statements) { this.statements = statements; }

    /** A statement line: "<statement date> <due-total>". */
    public static String statementLine(java.sql.Date date, BigDecimal dueTotal) {
        return (date == null ? "" : date.toLocalDate().toString()) + " "
                + (dueTotal == null ? "n/a" : dueTotal.setScale(2).toPlainString());
    }
    /** A hold from a date to an optional to-date (null: open-ended), both days included. */
    public record Hold(LocalDate from, LocalDate to) {
        public boolean covers(LocalDate date) {
            return date != null && !date.isBefore(from) && (to == null || !date.isAfter(to));
        }
    }
    /** Whether the person has any hold. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** The person's holds, in the order they were added. */
    public java.util.List<Hold> getHolds() { return holds; }
    public void setHolds(java.util.List<Hold> holds) { this.holds = holds; }
    /** Whether a hold of the person's covers the date. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.covers(date)); }
    /** Whether the claim counts in the live totals: OPEN, PENDING or SETTLED. A hold (the person's or the claim's)
     *  does not take it out — a hold only matters to the pools' cuts. */
    public boolean countsLive(Claim claim) {
        return claim.getStatus().counts();
    }
    /** Whether the person's retirement date has been reached on the date (the sheet's today on or after it). */
    public boolean retiredOn(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }
    /** Whether the claim counts in the live totals on the sheet's today: as {@link #countsLive(Claim)}, not deferred,
     *  and, once the person's retirement date is reached, not OPEN or PENDING unless a statement binds it. */
    public boolean countsLive(Claim claim, LocalDate today) {
        return countsLive(claim) && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isBound() && retiredOn(today));
    }
    /** Whether the claim counts toward claimed on the sheet's today: as {@link #countsLive(Claim, LocalDate)}
     *  (a hold does not take it out). */
    public boolean countsClaimed(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isBound() && retiredOn(today));
    }
    /** Whether the claim counts in a period ending on the date: by the status it had at the end of that day (see
     *  {@link Claim#statusAt}), and, as in the live totals on the sheet's today, not deferred and not open, unbound and
     *  once their retirement date is reached (a hold does not take it out). */
    public boolean countsAtEnd(Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus then = claim.statusAt(end);
        return then != null && then.counts() && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isBound() && retiredOn(today));
    }
    /** The ids of the people the person has named as patrons, in the order they were named. */
    public java.util.List<Long> getPatronIds() { return patronIds; }
    /** The names of the person's patrons, sorted. */
    public java.util.List<String> getPatronNames() { return patronNames; }
    public void setPatrons(java.util.List<Long> ids, java.util.List<String> names) {
        this.patronIds = ids;
        this.patronNames = names;
    }
    /** The person's aliases, sorted as names are compared. */
    public java.util.List<String> getAliases() { return aliases; }
    public void setAliases(java.util.List<String> aliases) { this.aliases = aliases; }
    /** Whether the person's name or an alias is used by someone else on a sheet of the sheet's tree. */
    public boolean isClashing() { return clashing; }
    public void setClashing(boolean clashing) { this.clashing = clashing; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    public void setStatementCount(int statementCount) { this.statementCount = statementCount; }
    public void setStatedTotal(BigDecimal statedTotal) { this.statedTotal = statedTotal; }
    public void setStatementDate(LocalDate statementDate) { this.statementDate = statementDate; }
    public void setName(String name) { this.name = name; }
    /** The sheet's today when the person was added; null when not known. */
    private LocalDate addedOn;
    public LocalDate getAddedOn() { return addedOn; }
    public void setAddedOn(LocalDate addedOn) { this.addedOn = addedOn; }

    /** The person's place in the sheet's list: people are listed by place, lowest first. */
    private long place;
    public long getPlace() { return place; }
    public void setPlace(long place) { this.place = place; }

    /** The sheet the person was transferred from; null when not transferred in. */
    private String origin;
    public String getOrigin() { return origin; }
    public void setOrigin(String origin) { this.origin = origin; }

    /** The sheet's today when the person arrived by transfer; null when not transferred in. */
    private LocalDate arrivedOn;
    public LocalDate getArrivedOn() { return arrivedOn; }
    public void setArrivedOn(LocalDate arrivedOn) { this.arrivedOn = arrivedOn; }
    public void setVersion(int version) { this.version = version; }

    /** A steward's flag: its reason and until date; null when never flagged. */
    private String flagReason;
    private LocalDate flagUntil;
    public String getFlagReason() { return flagReason; }
    public LocalDate getFlagUntil() { return flagUntil; }
    public void setFlag(String reason, LocalDate until) {
        this.flagReason = reason;
        this.flagUntil = until;
    }
    /** The user who may approve or reject the person's PENDING claims as a steward may; null for none. */
    private String approver;
    public String getApprover() { return approver; }
    public void setApprover(String approver) { this.approver = approver; }
    /** Whether the person's flag is in force on a date: on or before its until date. */
    public boolean flaggedOn(LocalDate date) {
        return flagReason != null && flagUntil != null && date != null && !date.isAfter(flagUntil);
    }
    /** The flag's reason while it is in force on the sheet's today; "" otherwise. */
    public String getFlagShown() { return flaggedOn(today) ? flagReason : ""; }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.stereotype.Repository;

/** The rate store: percents per grade, each from a date (or from the beginning of time), kept per sheet. */
@Repository
public class Rates {

    private final JdbcTemplate jdbc;

    private final Sheets sheets;

    public Rates(JdbcTemplate jdbc, Sheets sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** The sheet's rates, by grade then from-date (from the beginning of time first), each with the older versions it
     *  replaced (newest first) for the claims a forward-only newer version does not apply to. */
    public List<RateResponse> list(String sheetId) {
        Map<String, List<RateResponse.Earlier>> earlier = new HashMap<>();
        jdbc.query("SELECT grade, from_date, rate, to_date, after_mark FROM rate_version WHERE sheet_id = ? ORDER BY version DESC",
                (RowCallbackHandler) rs -> {
                    Date to = rs.getDate("to_date");
                    earlier.computeIfAbsent(rs.getString("grade") + "|" + rs.getDate("from_date"), k -> new ArrayList<>())
                            .add(new RateResponse.Earlier(rs.getBigDecimal("rate").setScale(2).toPlainString(),
                                    to == null ? "" : to.toLocalDate().toString(), rs.getLong("after_mark")));
                }, sheetId);
        return jdbc.query("SELECT grade, rate, from_date, to_date, version, after_mark FROM rate WHERE sheet_id = ? ORDER BY grade, from_date NULLS FIRST",
                (rs, i) -> {
                    Date from = rs.getDate("from_date");
                    Date to = rs.getDate("to_date");
                    return new RateResponse(rs.getString("grade"), rs.getBigDecimal("rate").setScale(2).toPlainString(),
                            from == null ? "" : from.toLocalDate().toString(), to == null ? "" : to.toLocalDate().toString(),
                            rs.getInt("version"), rs.getLong("after_mark"),
                            earlier.getOrDefault(rs.getString("grade") + "|" + from, List.of()));
                },
                sheetId);
    }

    /** A claim's mark later than every rate's: asks for the rate in force without regard to forward-only rates (the
     *  rates panel, the rate preview and the rate calendar show that one). */
    public static final long IN_FORCE = Long.MAX_VALUE;

    /** Whether a rate (version) saved with this mark applies to a claim with that one: a rate applying to every claim
     *  (mark 0) always; a forward-only one only to a claim that arrived after it was saved. */
    public static boolean applies(long afterMark, long claimMark) {
        return afterMark == 0 || claimMark > afterMark;
    }

    /** The rate for a grade in force on a date for a claim with a mark (see {@link #applies}). */
    @FunctionalInterface
    public interface Lookup {
        BigDecimal rate(String grade, LocalDate date, long claimMark);
    }

    /** How many levels up a sheet's parents are asked for a rate the sheet has not. */
    public static final int ANCESTOR_LEVELS = 3;

    /** The sheet's ancestors asked for a rate it has not: its parent, then the parent's parent, up to
     *  {@link #ANCESTOR_LEVELS} levels up; then, for a clone, the sheet it was cloned from and that sheet's own
     *  ancestors, and so on. */
    public List<String> ancestors(String sheetId) {
        return chain(sheetId, sheets::parent, sheets::source);
    }

    /** The chain of sheets asked for a rate the sheet has not, by the parent and source of each: the sheet's parents up to
     *  {@link #ANCESTOR_LEVELS} levels up, then its source (when it is a clone) and that one's parents and source in turn;
     *  each sheet once. */
    public static List<String> chain(String sheetId, java.util.function.UnaryOperator<String> parent,
            java.util.function.UnaryOperator<String> source) {
        List<String> chain = new ArrayList<>();
        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
        for (String from = sheetId; ; ) {
            int levels = 0;
            for (String at = parent.apply(from); at != null && levels < ANCESTOR_LEVELS && seen.add(at); at = parent.apply(at)) {
                chain.add(at);
                levels++;
            }
            String next = source.apply(from);
            if (next == null || !seen.add(next)) {
                return chain;
            }
            chain.add(next);
            from = next;
        }
    }

    /** The rates of the sheet's ancestors (see {@link #ancestors(String)}), nearest first. */
    public List<List<RateResponse>> inherited(String sheetId) {
        return ancestors(sheetId).stream().map(this::list).toList();
    }

    /** The rate for a grade on the sheet in force on a date (see {@link #findOwn}); when the sheet has
     *  none, its parent's, then the parent's parent's, up to {@link #ANCESTOR_LEVELS} levels up, then a clone's source's
     *  (see {@link #ancestors}); null when none has one. */
    public BigDecimal find(String sheetId, String grade, LocalDate date) {
        return find(sheetId, grade, date, IN_FORCE);
    }

    /** The rate for a grade on the sheet that applies to the claim on its date (see {@link #find(String, String, LocalDate, long)}). */
    public BigDecimal find(net.officefloor.hq.app.claim.Claim claim, String grade) {
        return find(claim.getSheetId(), grade, claim.getDate(), claim.getRateMark());
    }

    /** As {@link #find(String, String, LocalDate)}, for a claim with a mark: the rates that apply to it only. */
    public BigDecimal find(String sheetId, String grade, LocalDate date, long claimMark) {
        BigDecimal own = findOwn(sheetId, grade, date, claimMark);
        if (own != null) {
            return own;
        }
        for (String ancestor : ancestors(sheetId)) {
            BigDecimal rate = findOwn(ancestor, grade, date, claimMark);
            if (rate != null) {
                return rate;
            }
        }
        return null;
    }

    /** The rate for a grade set on the sheet itself in force on a date for a claim with a mark: of the versions that apply
     *  to it (see {@link #applies}), the newest of the one with the latest from-date on or before the date; null when none
     *  applies, or when that one's to-date is before the date. */
    public BigDecimal findOwn(String sheetId, String grade, LocalDate date, long claimMark) {
        Date on = Date.valueOf(date);
        String cols = "SELECT from_date, version, rate, to_date, after_mark FROM ";
        String where = " WHERE sheet_id = ? AND grade = ? AND (from_date IS NULL OR from_date <= ?)";
        List<Object[]> found = jdbc.query(cols + "rate" + where + " UNION ALL " + cols + "rate_version" + where
                + " ORDER BY from_date DESC NULLS LAST, version DESC",
                (rs, i) -> new Object[] { rs.getBigDecimal("rate"), rs.getDate("to_date"), rs.getLong("after_mark") },
                sheetId, grade, on, sheetId, grade, on);
        for (Object[] row : found) {
            if (applies((Long) row[2], claimMark)) {
                Date to = (Date) row[1];
                return to != null && to.before(on) ? null : (BigDecimal) row[0];
            }
        }
        return null;
    }

    /** The due on an amount at a rate (a percent), rounded to cents by the claim's rounding; null when there is no rate. */
    public static BigDecimal due(BigDecimal amount, BigDecimal rate, RoundingMode rounding) {
        return rate == null ? null : amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
    }

    /** Set the grade's rate from a date (null: from the beginning of time) through a date (null: no
     *  end) as a new version: one already there from the same date is kept as an older version. One from a date on or
     *  after the sheet's today is forward-only: it draws a mark, and applies only to claims arriving after it. */
    public void set(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal rate) {
        Date fromDate = from == null ? null : Date.valueOf(from);
        long afterMark = from != null && !from.isBefore(sheets.today(sheetId))
                ? jdbc.queryForObject("SELECT NEXT VALUE FOR rate_mark_seq", Long.class) : 0L;
        String sameFrom = fromDate == null ? " AND from_date IS NULL" : " AND from_date = ?";
        Object[] key = fromDate == null ? new Object[] { sheetId, grade } : new Object[] { sheetId, grade, fromDate };
        jdbc.update("INSERT INTO rate_version (sheet_id, grade, from_date, version, rate, to_date, after_mark)"
                + " SELECT sheet_id, grade, from_date, version, rate, to_date, after_mark FROM rate WHERE sheet_id = ? AND grade = ?" + sameFrom, key);
        Integer latest = jdbc.queryForObject("SELECT MAX(version) FROM rate WHERE sheet_id = ? AND grade = ?" + sameFrom, Integer.class, key);
        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ?" + sameFrom, key);
        jdbc.update("INSERT INTO rate (sheet_id, grade, rate, from_date, to_date, version, after_mark) VALUES (?, ?, ?, ?, ?, ?, ?)",
