import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Soft-closes an open period, by the roles the sheet allows to close (see {@link PeriodCloser#softClose}). */
public class SoftClosePeriod {
    public void softClose(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods,
            Settings settings, PeriodCloser closer, ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (!settings.allows(sheetId, request.user(), "close")) {
            throw new InvalidPeriodException("Your role may not close a period");
        }
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (period.closed() || period.softClosed()) {
            throw new InvalidPeriodException("The period " + name + " is already closed or soft-closed");
        }
        closer.softClose(sheetId, period, request.user());
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Locks a period, by a steward only: a locked period cannot be reopened until it is unlocked. */
public class LockPeriod {
    public void lock(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods, Settings settings, Audit audit,
            ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new InvalidPeriodException("Only a steward may lock a period");
        }
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (period.locked()) {
            throw new InvalidPeriodException("The period " + name + " is already locked");
        }
        periods.setLocked(sheetId, name, true);
        audit.recordOnCommit("PERIOD_LOCKED sheet=" + sheetId + " by=" + request.user() + " period=" + name);
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reopens a closed or soft-closed period, by the roles the sheet's reopen permission allows (by default a steward only): its fixed due-total is dropped, so it totals its
 *  claims' current figures again. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods, Settings settings, Audit audit,
            ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (!settings.allows(sheetId, request.user(), "reopen")) {
            throw new InvalidPeriodException("Your role may not reopen a period");
        }
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (!period.closed() && !period.softClosed()) {
            throw new InvalidPeriodException("The period " + name + " is not closed");
        }
        if (period.locked()) {
            throw new InvalidPeriodException("The period " + name + " is locked");
        }
        periods.reopen(sheetId, name);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + request.user() + " period=" + name);
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.Person;

/** A claim added while its period (by its due-by) is soft-closed is a late entry: marked so, and audited as LATE_ENTRY after its CLAIM_ADDED. */
final class LateEntry {

    private LateEntry() {
    }

    static void mark(Claim claim, Person person, String user, Claims claims, Periods periods, Audit audit) {
        if (periods.isSoftClosed(claim.getSheetId(), claim.getPeriodDate())) {
            claims.markLateEntry(claim);
            audit.recordOnCommit(ClaimAudit.line("LATE_ENTRY", user, person, claim, claim.getNumber()));
        }
    }
}

